SET local check_function_bodies = off;

ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM "anon";

ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM "authenticated";

ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM "service_role";

CREATE SCHEMA "private";

CREATE EXTENSION "citext" SCHEMA "public";

CREATE EXTENSION "hypopg" SCHEMA "extensions";

CREATE EXTENSION "index_advisor" SCHEMA "extensions";

CREATE EXTENSION "pg_jsonschema" SCHEMA "extensions";

CREATE EXTENSION "pg_trgm" SCHEMA "public";

CREATE TABLE "public"."campaigns" (
  "id"        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "createdAt" timestamp with time zone DEFAULT now(),
  "createdBy" uuid                     NOT NULL,
  "title"     public.citext            NOT NULL,
  CONSTRAINT "campaigns_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."campaigns"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."combat_events" (
  "id"          bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "encounterId" bigint                   NOT NULL,
  "rowId"       text                     NOT NULL,
  "round"       integer                  NOT NULL DEFAULT 1,
  "type"        text                     NOT NULL,
  "payload"     jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "createdBy"   uuid,
  "actorName"   text,
  "createdAt"   timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "combat_events_pkey" PRIMARY KEY (id),
  CONSTRAINT "combat_events_type_check"
    CHECK
    ((type = ANY (ARRAY['hp'::text, 'ac'::text, 'condition_added'::text, 'condition_removed'::text, 'death_save'::text, 'concentration_broken'::text, 'concentration_started'::text,
    'stabilized'::text, 'died'::text])))
);

ALTER TABLE "public"."combat_events"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."features" (
  "id"        bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "createdAt" timestamp with time zone NOT NULL DEFAULT now(),
  "title"     text                     NOT NULL,
  "text"      text                     NOT NULL,
  "voted"     jsonb                    NOT NULL DEFAULT '{"like": [], "dislike": []}'::jsonb,
  "createdBy" uuid                     NOT NULL,
  CONSTRAINT "features_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."features"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."homebrew_items" (
  "createdAt"                timestamp with time zone NOT NULL DEFAULT now(),
  "campaign"                 bigint                   NOT NULL,
  "name"                     public.citext            NOT NULL,
  "armorClass"               smallint,
  "hitPoints"                smallint,
  "link"                     text,
  "id"                       bigint                   GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."homebrew-items_id_seq") NOT NULL,
  "player"                   text,
  "actions"                  jsonb                    NOT NULL,
  "initiativeModifier"       text,
  "hitDice"                  text,
  "armorDetail"              text,
  "proficiencyBonus"         smallint,
  "passivePerception"        smallint,
  "speed"                    jsonb,
  "sight"                    jsonb,
  "languages"                jsonb,
  "abilityScores"            jsonb,
  "modifiers"                jsonb,
  "savingThrows"             jsonb,
  "skillBonuses"             jsonb,
  "resistancesAndImmunities" jsonb,
  "traits"                   jsonb,
  CONSTRAINT "chk_homebrew_ability_scores"
    CHECK
    ((("abilityScores" IS NULL) OR ((jsonb_typeof("abilityScores") = 'object'::text) AND ((("abilityScores" -> 'strength'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" ->
    'strength'::text)) = 'number'::text) AND (((("abilityScores" ->> 'strength'::text))::integer >= 1) AND ((("abilityScores" ->> 'strength'::text))::integer <= 30)))) AND
    ((("abilityScores" -> 'dexterity'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" -> 'dexterity'::text)) = 'number'::text) AND (((("abilityScores" ->>
    'dexterity'::text))::integer >= 1) AND ((("abilityScores" ->> 'dexterity'::text))::integer <= 30)))) AND
    ((("abilityScores" -> 'constitution'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" -> 'constitution'::text)) = 'number'::text) AND (((("abilityScores" ->>
    'constitution'::text))::integer >= 1) AND ((("abilityScores" ->> 'constitution'::text))::integer <= 30)))) AND
    ((("abilityScores" -> 'intelligence'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" -> 'intelligence'::text)) = 'number'::text) AND (((("abilityScores" ->>
    'intelligence'::text))::integer >= 1) AND ((("abilityScores" ->> 'intelligence'::text))::integer <= 30)))) AND
    ((("abilityScores" -> 'wisdom'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" -> 'wisdom'::text)) = 'number'::text) AND (((("abilityScores" ->> 'wisdom'::text))::integer >=
    1) AND ((("abilityScores" ->> 'wisdom'::text))::integer <= 30)))) AND
    ((("abilityScores" -> 'charisma'::text) IS NULL) OR ((jsonb_typeof(("abilityScores" -> 'charisma'::text)) = 'number'::text) AND (((("abilityScores" ->>
    'charisma'::text))::integer >= 1) AND ((("abilityScores" ->> 'charisma'::text))::integer <= 30))))))),
  CONSTRAINT "chk_homebrew_modifiers"
    CHECK
    (((modifiers IS NULL) OR ((jsonb_typeof(modifiers) = 'object'::text) AND (((modifiers -> 'strength'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'strength'::text)) =
    'number'::text) AND ((((modifiers ->> 'strength'::text))::integer >= '-10'::integer) AND (((modifiers ->> 'strength'::text))::integer <= 20)))) AND
    (((modifiers -> 'dexterity'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'dexterity'::text)) = 'number'::text) AND ((((modifiers ->> 'dexterity'::text))::integer >=
    '-10'::integer) AND (((modifiers ->> 'dexterity'::text))::integer <= 20)))) AND
    (((modifiers -> 'constitution'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'constitution'::text)) = 'number'::text) AND ((((modifiers ->> 'constitution'::text))::integer >=
    '-10'::integer) AND (((modifiers ->> 'constitution'::text))::integer <= 20)))) AND
    (((modifiers -> 'intelligence'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'intelligence'::text)) = 'number'::text) AND ((((modifiers ->> 'intelligence'::text))::integer >=
    '-10'::integer) AND (((modifiers ->> 'intelligence'::text))::integer <= 20)))) AND
    (((modifiers -> 'wisdom'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'wisdom'::text)) = 'number'::text) AND ((((modifiers ->> 'wisdom'::text))::integer >= '-10'::integer)
    AND (((modifiers ->> 'wisdom'::text))::integer <= 20)))) AND
    (((modifiers -> 'charisma'::text) IS NULL) OR ((jsonb_typeof((modifiers -> 'charisma'::text)) = 'number'::text) AND ((((modifiers ->> 'charisma'::text))::integer >=
    '-10'::integer) AND (((modifiers ->> 'charisma'::text))::integer <= 20))))))),
  CONSTRAINT "chk_homebrew_saving_throws"
    CHECK
    ((("savingThrows" IS NULL) OR ((jsonb_typeof("savingThrows") = 'object'::text) AND ((("savingThrows" -> 'strength'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" ->
    'strength'::text)) = 'number'::text) AND (((("savingThrows" ->> 'strength'::text))::integer >= '-10'::integer) AND ((("savingThrows" ->> 'strength'::text))::integer <= 20))))
    AND
    ((("savingThrows" -> 'dexterity'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" -> 'dexterity'::text)) = 'number'::text) AND (((("savingThrows" ->>
    'dexterity'::text))::integer >= '-10'::integer) AND ((("savingThrows" ->> 'dexterity'::text))::integer <= 20)))) AND
    ((("savingThrows" -> 'constitution'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" -> 'constitution'::text)) = 'number'::text) AND (((("savingThrows" ->>
    'constitution'::text))::integer >= '-10'::integer) AND ((("savingThrows" ->> 'constitution'::text))::integer <= 20)))) AND
    ((("savingThrows" -> 'intelligence'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" -> 'intelligence'::text)) = 'number'::text) AND (((("savingThrows" ->>
    'intelligence'::text))::integer >= '-10'::integer) AND ((("savingThrows" ->> 'intelligence'::text))::integer <= 20)))) AND
    ((("savingThrows" -> 'wisdom'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" -> 'wisdom'::text)) = 'number'::text) AND (((("savingThrows" ->> 'wisdom'::text))::integer >=
    '-10'::integer) AND ((("savingThrows" ->> 'wisdom'::text))::integer <= 20)))) AND
    ((("savingThrows" -> 'charisma'::text) IS NULL) OR ((jsonb_typeof(("savingThrows" -> 'charisma'::text)) = 'number'::text) AND (((("savingThrows" ->> 'charisma'::text))::integer
    >= '-10'::integer) AND ((("savingThrows" ->> 'charisma'::text))::integer <= 20))))))),
  CONSTRAINT "chk_homebrew_sight"
    CHECK
    (((sight IS NULL) OR ((jsonb_typeof(sight) = 'object'::text) AND (((sight -> 'normalSightRange'::text) IS NULL) OR ((jsonb_typeof((sight -> 'normalSightRange'::text)) =
    'number'::text) AND ((((sight ->> 'normalSightRange'::text))::numeric >= (0)::numeric) AND (((sight ->> 'normalSightRange'::text))::numeric <= (10000)::numeric)))) AND
    (((sight -> 'darkVisionRange'::text) IS NULL) OR ((jsonb_typeof((sight -> 'darkVisionRange'::text)) = 'number'::text) AND ((((sight ->> 'darkVisionRange'::text))::numeric >=
    (0)::numeric) AND (((sight ->> 'darkVisionRange'::text))::numeric <= (10000)::numeric)))) AND
    (((sight -> 'blindSightRange'::text) IS NULL) OR ((jsonb_typeof((sight -> 'blindSightRange'::text)) = 'number'::text) AND ((((sight ->> 'blindSightRange'::text))::numeric >=
    (0)::numeric) AND (((sight ->> 'blindSightRange'::text))::numeric <= (10000)::numeric)))) AND
    (((sight -> 'tremorSenseRange'::text) IS NULL) OR ((jsonb_typeof((sight -> 'tremorSenseRange'::text)) = 'number'::text) AND ((((sight ->> 'tremorSenseRange'::text))::numeric >=
    (0)::numeric) AND (((sight ->> 'tremorSenseRange'::text))::numeric <= (10000)::numeric)))) AND
    (((sight -> 'trueSightRange'::text) IS NULL) OR ((jsonb_typeof((sight -> 'trueSightRange'::text)) = 'number'::text) AND ((((sight ->> 'trueSightRange'::text))::numeric >=
    (0)::numeric) AND (((sight ->> 'trueSightRange'::text))::numeric <= (10000)::numeric))))))),
  CONSTRAINT "chk_homebrew_skill_bonuses"
    CHECK
    ((("skillBonuses" IS NULL) OR ((jsonb_typeof("skillBonuses") = 'object'::text) AND ((("skillBonuses" -> 'acrobatics'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" ->
    'acrobatics'::text)) = 'number'::text) AND
    (((("skillBonuses" ->> 'acrobatics'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'acrobatics'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'animalHandling'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'animalHandling'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'animalHandling'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'animalHandling'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'arcana'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'arcana'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'arcana'::text))::integer >=
    '-10'::integer) AND ((("skillBonuses" ->> 'arcana'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'athletics'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'athletics'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'athletics'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'athletics'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'deception'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'deception'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'deception'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'deception'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'history'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'history'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'history'::text))::integer >=
    '-10'::integer) AND ((("skillBonuses" ->> 'history'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'insight'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'insight'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'insight'::text))::integer >=
    '-10'::integer) AND ((("skillBonuses" ->> 'insight'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'intimidation'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'intimidation'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'intimidation'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'intimidation'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'investigation'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'investigation'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'investigation'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'investigation'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'medicine'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'medicine'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'medicine'::text))::integer
    >= '-10'::integer) AND ((("skillBonuses" ->> 'medicine'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'nature'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'nature'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'nature'::text))::integer >=
    '-10'::integer) AND ((("skillBonuses" ->> 'nature'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'perception'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'perception'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'perception'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'perception'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'performance'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'performance'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'performance'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'performance'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'persuasion'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'persuasion'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'persuasion'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'persuasion'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'religion'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'religion'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'religion'::text))::integer
    >= '-10'::integer) AND ((("skillBonuses" ->> 'religion'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'sleightOfHand'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'sleightOfHand'::text)) = 'number'::text) AND (((("skillBonuses" ->>
    'sleightOfHand'::text))::integer >= '-10'::integer) AND ((("skillBonuses" ->> 'sleightOfHand'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'stealth'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'stealth'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'stealth'::text))::integer >=
    '-10'::integer) AND ((("skillBonuses" ->> 'stealth'::text))::integer <= 20)))) AND
    ((("skillBonuses" -> 'survival'::text) IS NULL) OR ((jsonb_typeof(("skillBonuses" -> 'survival'::text)) = 'number'::text) AND (((("skillBonuses" ->> 'survival'::text))::integer
    >= '-10'::integer) AND ((("skillBonuses" ->> 'survival'::text))::integer <= 20))))))),
  CONSTRAINT "chk_homebrew_speed"
    CHECK
    (((speed IS NULL) OR ((jsonb_typeof(speed) = 'object'::text) AND (((speed -> 'walk'::text) IS NULL) OR ((jsonb_typeof((speed -> 'walk'::text)) = 'number'::text) AND ((((speed
    ->> 'walk'::text))::numeric >= (0)::numeric) AND (((speed ->> 'walk'::text))::numeric <= (500)::numeric)))) AND
    (((speed -> 'crawl'::text) IS NULL) OR ((jsonb_typeof((speed -> 'crawl'::text)) = 'number'::text) AND ((((speed ->> 'crawl'::text))::numeric >= (0)::numeric) AND (((speed ->>
    'crawl'::text))::numeric <= (500)::numeric)))) AND
    (((speed -> 'fly'::text) IS NULL) OR ((jsonb_typeof((speed -> 'fly'::text)) = 'number'::text) AND ((((speed ->> 'fly'::text))::numeric >= (0)::numeric) AND (((speed ->>
    'fly'::text))::numeric <= (500)::numeric)))) AND
    (((speed -> 'swim'::text) IS NULL) OR ((jsonb_typeof((speed -> 'swim'::text)) = 'number'::text) AND ((((speed ->> 'swim'::text))::numeric >= (0)::numeric) AND (((speed ->>
    'swim'::text))::numeric <= (500)::numeric)))) AND
    (((speed -> 'burrow'::text) IS NULL) OR ((jsonb_typeof((speed -> 'burrow'::text)) = 'number'::text) AND ((((speed ->> 'burrow'::text))::numeric >= (0)::numeric) AND (((speed
    ->> 'burrow'::text))::numeric <= (500)::numeric)))) AND
    (((speed -> 'climb'::text) IS NULL) OR ((jsonb_typeof((speed -> 'climb'::text)) = 'number'::text) AND ((((speed ->> 'climb'::text))::numeric >= (0)::numeric) AND (((speed ->>
    'climb'::text))::numeric <= (500)::numeric)))) AND (((speed -> 'hover'::text) IS NULL) OR (jsonb_typeof((speed -> 'hover'::text)) = 'boolean'::text))))),
  CONSTRAINT "homebrew-items_pkey" PRIMARY KEY (id),
  CONSTRAINT "homebrew_items_actions_check"
    CHECK
    (extensions.jsonb_matches_schema('{   "type": "array",   "minItems": 0,   "items": {     "type": "object",     "additionalProperties": false,     "required": ["name", "desc", "actionType", "attacks"],     "properties": {       "name": { "type": "string" },       "desc": { "type": "string" },       "actionType": { "enum": ["action", "bonusAction", "reaction", "legendaryAction", "mythicAction", "lairAction", "specialAbility"] },       "legendaryActionCost": { "type": "integer" },       "limitedToForm": { "type": "string" },       "usageLimits": {         "type": "object",         "required": ["type", "param"],         "additionalProperties": false,         "properties": {           "type": { "enum": ["perDay", "recharge", "atWill", "perRest"] },           "param": { "type": "integer" }         }       },       "attacks": {         "type": "array",         "minItems": 0,         "items": {           "type": "object",           "additionalProperties": false,           "required": ["name", "attackType", "distanceUnit"],           "properties": {             "name": { "type": "string" },             "attackType": { "enum": ["melee", "ranged", "meleeSpell", "rangedSpell"] },             "toHitMod": { "type": "integer" },             "distanceUnit": { "enum": ["feet", "miles"] },             "reach": { "type": "integer" },             "range": { "type": "integer" },             "longRange": { "type": "integer" },             "targetCreatureOnly": { "type": "boolean" },             "damageDieCount": { "type": "integer" },             "damageDieType": { "enum": ["d4", "d6", "d8", "d10", "d12", "d20", "d100"] },             "damageBonus": { "type": "integer" },             "damageType": { "enum": ["acid", "bludgeoning", "cold", "fire", "force", "lightning", "necrotic", "piercing", "poison", "psychic", "radiant", "slashing", "thunder"] },             "extraDamageDieCount": { "type": "integer" },             "extraDamageDieType": { "enum": ["d4", "d6", "d8", "d10", "d12", "d20", "d100"] },             "extraDamageBonus": { "type": "integer" },             "extraDamageType": { "enum": ["acid", "bludgeoning", "cold", "fire", "force", "lightning", "necrotic", "piercing", "poison", "psychic", "radiant", "slashing", "thunder"] },             "spellSave": { "type": "integer" },             "spellSaveType": { "enum": ["strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma"] }           }         }       }     }   } }'::json, actions))
);

ALTER TABLE "public"."homebrew_items"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."initiative_sheets" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "createdAt"   timestamp with time zone DEFAULT now(),
  "title"       public.citext            NOT NULL,
  "round"       smallint                 NOT NULL DEFAULT '1'::smallint,
  "rows"        jsonb                    NOT NULL,
  "info"        text,
  "campaign"    bigint,
  "activeIndex" smallint                 NOT NULL DEFAULT '0'::smallint,
  "infoCards"   jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "settings"    jsonb                    DEFAULT '{"rows": [], "spacing": "normal", "modified": false, "negative": false}'::jsonb,
  "version"     integer                  NOT NULL DEFAULT 0,
  CONSTRAINT "initiative_sheets_info_cards_schema"
