    (extensions.jsonb_matches_schema('{"type":"array","items":{"type":"object","additionalProperties":false,"required":["name","desc","actionType","attacks"],"properties":{"name":{"type":"string"},"desc":{"type":"string"},"actionType":{"enum":["action","bonusAction","reaction","legendaryAction","mythicAction","lairAction","specialAbility"]},"legendaryActionCost":{"type":"integer"},"limitedToForm":{"type":"string"},"usageLimits":{"type":"object","additionalProperties":false,"required":["type","param"],"properties":{"type":{"enum":["perDay","recharge","atWill","perRest"]},"param":{"type":"integer"}}},"attacks":{"type":"array","items":{"type":"object","additionalProperties":false,"required":["name","attackType","distanceUnit"],"properties":{"name":{"type":"string"},"attackType":{"enum":["melee","ranged","meleeSpell","rangedSpell"]},"distanceUnit":{"enum":["feet","miles"]},"toHitMod":{"type":"integer"},"reach":{"type":"integer"},"range":{"type":"integer"},"longRange":{"type":"integer"},"targetCreatureOnly":{"type":"boolean"},"damageDieCount":{"type":"integer"},"damageDieType":{"enum":["d3","d4","d6","d8","d10","d12","d20","d100"]},"damageBonus":{"type":"integer"},"damageType":{"enum":["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"]},"extraDamageDieCount":{"type":"integer"},"extraDamageDieType":{"enum":["d3","d4","d6","d8","d10","d12","d20","d100"]},"extraDamageBonus":{"type":"integer"},"extraDamageType":{"enum":["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"]},"spellSave":{"type":"integer"},"spellSaveType":{"enum":["strength","dexterity","constitution","intelligence","wisdom","charisma"]}}}}}}}'::json, actions)),
  CONSTRAINT "srd_monsters_alignment_check"
    CHECK
    ((alignment = ANY (ARRAY['lawfulGood'::text, 'neutralGood'::text, 'chaoticGood'::text, 'lawfulNeutral'::text, 'trueNeutral'::text, 'chaoticNeutral'::text, 'lawfulEvil'::text,
    'neutralEvil'::text, 'chaoticEvil'::text]))),
  CONSTRAINT "srd_monsters_hit_dice_schema"
