    (extensions.jsonb_matches_schema('{"type":"object","additionalProperties":false,"required":["hitDiceCount","hitDiceType"],"properties":{"hitDiceCount":{"type":"integer"},"hitDiceType":{"enum":["d3","d4","d6","d8","d10","d12","d20","d100"]},"hitDiceBonus":{"type":"integer"}}}'::json, "hitDice")),
