    CHECK
    (extensions.jsonb_matches_schema('{"type":"array","items":{"type":"object","additionalProperties":false,"required":["name","desc"],"properties":{"name":{"type":"string"},"desc":{"type":"string"}}}}'::json, languages)),
  CONSTRAINT "srd_monsters_modifiers_schema"
