    CHECK
    (extensions.jsonb_matches_schema('{"type":"object","additionalProperties":false,"required":["damageImmunities","damageResistances","damageVulnerabilities","conditionImmunities"],"properties":{"damageImmunities":{"type":"array","items":{"enum":["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"]}},"damageResistances":{"type":"array","items":{"enum":["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"]}},"damageVulnerabilities":{"type":"array","items":{"enum":["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"]}},"conditionImmunities":{"type":"array","items":{"enum":["blinded","charmed","deafened","frightened","grappled","incapacitated","invisible","paralyzed","petrified","poisoned","prone","restrained","stunned","unconscious","exhaustion"]}}}}'::json, "resistancesAndImmunities")),
  CONSTRAINT "srd_monsters_saving_throws_schema"
    CHECK
    (extensions.jsonb_matches_schema('{"type":"object","additionalProperties":false,"required":["strength","dexterity","constitution","intelligence","wisdom","charisma"],"properties":{"strength":{"type":"integer"},"dexterity":{"type":"integer"},"constitution":{"type":"integer"},"intelligence":{"type":"integer"},"wisdom":{"type":"integer"},"charisma":{"type":"integer"}}}'::json, "savingThrows")),
