CREATE OR REPLACE FUNCTION private.campaign_role (
  p_campaign bigint
)
  RETURNS public.user_role
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select coalesce(
    (select 'Owner'::public.user_role from public.campaigns c
      where c.id = p_campaign and c."createdBy" = (select auth.uid())),
    (select t.role from public.team t
      where t.campaign = p_campaign and t."user" = (select auth.uid()) limit 1))
$function$;

CREATE OR REPLACE FUNCTION private.can_read_campaign (
  p_campaign bigint
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select private.campaign_role(p_campaign) is not null
     or exists (
       select 1 from public.join_campaign j
       where j.campaign = p_campaign and j."user" = (select auth.uid())
     )
$function$;

CREATE OR REPLACE FUNCTION private.can_read_profile (
  p_profile uuid
)
  RETURNS boolean
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  with my_campaigns as (
    select c.id from public.campaigns c
    where c."createdBy" = (select auth.uid())
    union
    select t.campaign from public.team t
    where t."user" = (select auth.uid())
    union
    select j.campaign from public.join_campaign j
    where j."user" = (select auth.uid())
  )
  select p_profile = (select auth.uid())
     or exists (
       select 1 from public.campaigns c
       join my_campaigns m on m.id = c.id
       where c."createdBy" = p_profile
     )
     or exists (
       select 1 from public.team t
       join my_campaigns m on m.id = t.campaign
       where t."user" = p_profile
     )
     or exists (
       select 1 from public.join_campaign j
       join my_campaigns m on m.id = j.campaign
       where j."user" = p_profile
     )
     or exists (
       select 1 from public.initiative_sheets s
       join my_campaigns m on m.id = s.campaign
       where s."createdBy" = p_profile
     )
$function$;

CREATE OR REPLACE FUNCTION public.apply_live_action (
  p_encounter bigint,
  p_row_id    text,
  p_patch     jsonb
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_rows jsonb;
  v_row jsonb;
begin
  update public.initiative_sheets
  set rows = coalesce((
    select jsonb_agg(
      case when elem->>'id' = p_row_id then elem || p_patch else elem end
    )
    from jsonb_array_elements(rows) as elem
  ), rows)
  where id = p_encounter
  returning rows into v_rows;

  if v_rows is null then
    raise exception 'encounter % not found', p_encounter using errcode = 'P0002';
  end if;

  select elem into v_row
  from jsonb_array_elements(v_rows) as elem
  where elem->>'id' = p_row_id;

  if v_row is null then
    raise exception 'row % not found on encounter %', p_row_id, p_encounter using errcode = 'P0002';
  end if;

  return v_row;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."apply_live_action"(bigint, text, jsonb) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.claim_live_seat (
  p_session   uuid,
  p_row       text,
  p_name      text,
  p_spectator boolean
)
  RETURNS json
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_seats jsonb;
  v_seat json;
begin
  select seats into v_seats
  from live_sessions
  where uuid = p_session
  for update;

  if not found then
    raise exception 'live session not found' using errcode = 'P0002';
  end if;

  if jsonb_array_length(v_seats) >= 20 then
    raise exception 'live session is full' using errcode = 'P0001';
  end if;

  if p_row is not null and exists (
    select 1 from jsonb_array_elements(v_seats) elem
    where elem->>'row' = p_row
  ) then
    raise exception 'row already claimed' using errcode = 'P0002';
  end if;

  v_seat := json_build_object(
    'seat', gen_random_uuid(),
    'row', p_row,
    'name', p_name,
    'spectator', p_spectator
  );

  update live_sessions
  set seats = v_seats || jsonb_build_array(v_seat)
  where uuid = p_session;

  return v_seat;
end;
$function$;

REVOKE ALL ON FUNCTION "public"."claim_live_seat"(uuid, text, text, boolean) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.create_profile()
  RETURNS TRIGGER
  LANGUAGE plpgsql
  SET search_path TO 'public', 'pg_temp'
  AS $function$begin
  insert into public.profiles (id)
  values (new.id);
  return new;
end;$function$;

