CREATE OR REPLACE FUNCTION public.is_valid_languages (
  _j jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  SELECT
    _j IS NULL OR (
      jsonb_typeof(_j) = 'array'
      AND jsonb_array_length(_j) <= 20
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(_j) AS lang
        WHERE jsonb_typeof(lang) <> 'string'
           OR length(lang #>> '{}') < 1
           OR length(lang #>> '{}') > 50
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_resistances (
  _j jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  SELECT
    _j IS NULL OR (
      jsonb_typeof(_j) = 'object'
      AND (
        _j->'damageImmunities' IS NULL OR (
          jsonb_typeof(_j->'damageImmunities') = 'array'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(_j->'damageImmunities') AS v
            WHERE v NOT IN ('acid','bludgeoning','cold','fire','force','lightning','necrotic','piercing','poison','psychic','radiant','slashing','thunder')
          )
        )
      )
      AND (
        _j->'damageResistances' IS NULL OR (
          jsonb_typeof(_j->'damageResistances') = 'array'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(_j->'damageResistances') AS v
            WHERE v NOT IN ('acid','bludgeoning','cold','fire','force','lightning','necrotic','piercing','poison','psychic','radiant','slashing','thunder')
          )
        )
      )
      AND (
        _j->'damageVulnerabilities' IS NULL OR (
          jsonb_typeof(_j->'damageVulnerabilities') = 'array'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(_j->'damageVulnerabilities') AS v
            WHERE v NOT IN ('acid','bludgeoning','cold','fire','force','lightning','necrotic','piercing','poison','psychic','radiant','slashing','thunder')
          )
        )
      )
      AND (
        _j->'conditionImmunities' IS NULL OR (
          jsonb_typeof(_j->'conditionImmunities') = 'array'
          AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(_j->'conditionImmunities') AS v
            WHERE v NOT IN ('blinded','charmed','deafened','frightened','grappled','incapacitated','invisible','paralyzed','petrified','poisoned','prone','restrained','stunned','unconscious','exhaustion')
          )
        )
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.is_valid_traits (
  _j jsonb
)
  RETURNS boolean
  LANGUAGE sql
  IMMUTABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  SELECT
    _j IS NULL OR (
      jsonb_typeof(_j) = 'array'
      AND jsonb_array_length(_j) <= 40
      AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(_j) AS t
        WHERE jsonb_typeof(t) <> 'object'
           OR t->>'name' IS NULL
           OR t->>'desc' IS NULL
           OR length(t->>'name') < 3
           OR length(t->>'name') > 30
           OR length(t->>'desc') < 10
           OR length(t->>'desc') > 1000
      )
    );
$function$;

CREATE OR REPLACE FUNCTION public.profile_cards (
  p_ids uuid[]
)
