  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
  select p.id, p.username, p.avatar
  from public.profiles p
  where p.id = any(p_ids)
$function$;

CREATE OR REPLACE FUNCTION public.reassign_live_seat (
  p_session uuid,
  p_seat    uuid,
  p_row     text
)
  RETURNS json
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_seats jsonb;
  v_seat jsonb;
begin
  select seats into v_seats
  from live_sessions
  where uuid = p_session
  for update;

  if not found then
    raise exception 'live session not found' using errcode = 'P0002';
  end if;

  select elem into v_seat
  from jsonb_array_elements(v_seats) elem
  where elem->>'seat' = p_seat::text;

  if v_seat is null then
    raise exception 'seat not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1 from jsonb_array_elements(v_seats) elem
    where elem->>'row' = p_row
    and elem->>'seat' != p_seat::text
  ) then
    raise exception 'row already claimed' using errcode = 'P0001';
  end if;

  update live_sessions
  set seats = (
    select jsonb_agg(
      case when elem->>'seat' = p_seat::text
        then jsonb_set(elem, '{row}', to_jsonb(p_row))
        else elem
      end
    )
    from jsonb_array_elements(v_seats) elem
  )
  where uuid = p_session;

  return jsonb_set(v_seat, '{row}', to_jsonb(p_row));
end;
$function$;

REVOKE ALL ON FUNCTION "public"."reassign_live_seat"(uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.remove_live_seat (
  p_session uuid,
  p_seat    uuid
)
  RETURNS json
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
  AS $function$
declare
  v_seats jsonb;
begin
  select seats into v_seats
  from live_sessions
  where uuid = p_session
  for update;

  if not found then
    raise exception 'live session not found' using errcode = 'P0002';
  end if;

  if not exists (
    select 1 from jsonb_array_elements(v_seats) elem
    where elem->>'seat' = p_seat::text
  ) then
    raise exception 'seat not found' using errcode = 'P0002';
  end if;

  update live_sessions
  set seats = (
    select coalesce(jsonb_agg(elem), '[]'::jsonb)
    from jsonb_array_elements(v_seats) elem
    where elem->>'seat' != p_seat::text
  )
  where uuid = p_session;

  return json_build_object('seat', p_seat);
end;
$function$;

REVOKE ALL ON FUNCTION "public"."remove_live_seat"(uuid, uuid) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.transfer_campaign_ownership (
  p_campaign       bigint,
  p_caller         uuid,
  p_new_owner      uuid,
  p_old_owner_role text
)
  RETURNS void
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_old_owner uuid;
  v_new_owner_pro boolean;
begin
  select "createdBy" into v_old_owner
  from campaigns where id = p_campaign for update;

  if v_old_owner is null then
    raise exception 'Campaign not found';
  end if;

  if v_old_owner <> p_caller then
    raise exception 'Only the owner can transfer ownership';
  end if;

  if v_old_owner = p_new_owner then
    raise exception 'Already the owner';
  end if;

  if not exists (
    select 1 from team where campaign = p_campaign and "user" = p_new_owner
  ) then
    raise exception 'New owner must be a team member';
  end if;

  select p."subscriptionType" = 'pro' into v_new_owner_pro
  from profiles p where p.id = p_new_owner;

  if coalesce(v_new_owner_pro, false) and p_old_owner_role <> 'Remove' then
    insert into team (campaign, "user", role)
    values (p_campaign, v_old_owner, p_old_owner_role::user_role);
  end if;

  delete from team where campaign = p_campaign and "user" = p_new_owner;

  update campaigns set "createdBy" = p_new_owner where id = p_campaign;
end $function$;

REVOKE ALL ON FUNCTION "public"."transfer_campaign_ownership"(bigint, uuid, uuid, text) FROM PUBLIC, "anon", "authenticated";

CREATE OR REPLACE FUNCTION public.vote_feature (
  p_feature bigint,
  p_vote    text
)
  RETURNS jsonb
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
declare
  v_uid uuid := (select auth.uid());
  v_self jsonb;
  v_like jsonb;
  v_dislike jsonb;
  v_votes jsonb;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  if p_vote is not null and p_vote not in ('like', 'dislike') then
    raise exception 'Invalid vote' using errcode = '22023';
  end if;

  v_self := to_jsonb(v_uid::text);

  select
    coalesce((
      select jsonb_agg(e)
      from jsonb_array_elements(coalesce(f.voted -> 'like', '[]'::jsonb)) e
      where e <> v_self
    ), '[]'::jsonb),
    coalesce((
      select jsonb_agg(e)
      from jsonb_array_elements(coalesce(f.voted -> 'dislike', '[]'::jsonb)) e
      where e <> v_self
    ), '[]'::jsonb)
  into v_like, v_dislike
  from public.features f
  where f.id = p_feature;

  if not found then
    raise exception 'Feature not found' using errcode = 'P0002';
  end if;

  if p_vote = 'like' then
    v_like := v_like || jsonb_build_array(v_self);
  elsif p_vote = 'dislike' then
    v_dislike := v_dislike || jsonb_build_array(v_self);
  end if;

  update public.features
  set voted = jsonb_build_object('like', v_like, 'dislike', v_dislike)
  where id = p_feature
  returning voted into v_votes;

  return v_votes;
end
$function$;

REVOKE ALL ON FUNCTION "public"."vote_feature"(bigint, text) FROM PUBLIC, "anon";

