ALTER TABLE "public"."initiative_sheets"
  ADD CONSTRAINT "initiative_sheets_created_by_fkey" FOREIGN KEY ("createdBy") REFERENCES public.profiles(id) ON DELETE CASCADE;

CREATE INDEX initiative_sheets_created_by_idx ON public.initiative_sheets USING btree ("createdBy");

CREATE POLICY "combat_events_select_member" ON "public"."combat_events"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.initiative_sheets s
  WHERE ((s.id = combat_events."encounterId") AND ((s."createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(s.campaign) IS NOT NULL))))));

CREATE POLICY "encounters_delete_own_or_admin" ON "public"."initiative_sheets"
  FOR DELETE
  TO "authenticated"
  USING ((("createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(campaign) = ANY (ARRAY['Owner'::public.user_role, 'Admin'::public.user_role]))));

CREATE POLICY "encounters_insert_own_or_member" ON "public"."initiative_sheets"
  FOR INSERT
  TO "authenticated"
  WITH CHECK ((("createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(campaign) IS NOT NULL)));

CREATE POLICY "encounters_select_own_or_member" ON "public"."initiative_sheets"
  FOR SELECT
  TO "authenticated"
  USING ((("createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(campaign) IS NOT NULL)));

CREATE POLICY "encounters_update_own_or_member" ON "public"."initiative_sheets"
  FOR UPDATE
  TO "authenticated"
  USING ((("createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(campaign) IS NOT NULL)))
  WITH CHECK ((("createdBy" = ( SELECT auth.uid() AS uid)) OR (private.campaign_role(campaign) IS NOT NULL)));

ALTER TABLE "public"."homebrew_items"
  ADD CONSTRAINT "chk_homebrew_languages" CHECK (public.is_valid_languages(languages));

ALTER TABLE "public"."homebrew_items"
  ADD CONSTRAINT "chk_homebrew_resistances" CHECK (public.is_valid_resistances("resistancesAndImmunities"));

ALTER TABLE "public"."homebrew_items"
  ADD CONSTRAINT "chk_homebrew_traits" CHECK (public.is_valid_traits(traits));

